let questKills=0,particles=[],floaters=[],cooldowns={};
function isBlocked(x,y){return x<40||y<40||x>world.w-40||y>world.h-40}
function useSkill(n){let now=performance.now();if(cooldowns[n]&&now<cooldowns[n])return;let nearest=null,d=999;slimes.forEach(s=>{if(!s.dead){let dd=Math.hypot(s.x-player.x,s.y-player.y);if(dd<d){d=dd;nearest=s}}});
 if(n==='1'||n==='2'||n==='4'){if(n==='1'&&d<75)damageSlime(nearest,38);else if(n==='2'&&d<190)damageSlime(nearest,30);else if(n==='4'){player.x+=player.dir*120;if(isBlocked(player.x,player.y))player.x-=player.dir*120}cooldowns[n]=now+(n==='2'?1800:n==='1'?700:2500)}
