 document.querySelector(`[data-key="${n}"]`)?.classList.add('cool');setTimeout(()=>document.querySelector(`[data-key="${n}"]`)?.classList.remove('cool'),n==='3'?4000:n==='2'?1800:n==='4'?2500:700)}
function damageSlime(s,amount){if(!s)return;s.hp-=amount;s.hit=12;floater(s.x,s.y,amount,'#fff5bd');player.mp=Math.max(0,player.mp-2);if(s.hp<=0){s.dead=true;s.respawn=180;questKills=Math.min(5,questKills+1);player.exp+=14;if(player.exp>=100){player.exp-=100;player.lvl++;player.maxhp+=25;player.hp=player.maxhp}questProg();killPulse(s.x,s.y)}}
function floater(x,y,text,color){floaters.push({x,y,text,color,t:50})}function killPulse(x,y){for(let i=0;i<12;i++)particles.push({x,y,vx:(Math.random-.5)*3,vy:(Math.random-.5)*3,t:35,c:'#dff8b8'})}
function questProg(){document.getElementById('questprog').textContent=`${questKills} / 5 slain`;if(questKills>=5){document.getElementById('questtext').textContent='Quest selesai! Kembali ke Lina';document.getElementById('questprog').textContent='Hadiah: +240 EXP, +80 Zeny'}}
function drawGround(){ctx.fillStyle='#3f7048';ctx.fillRect(camera.x,camera.y,W,H);ctx.fillStyle='#47794c';for(let x=-((camera.x*1)%90)-90;x<W;x+=90)for(let y=-((camera.y*.7)%90)-90;y<H;y+=90){ctx.globalAlpha=.18;ctx.beginPath();ctx.ellipse(x-camera.x*.001,y-camera.y*.001,40,25,0,0,7);ctx.fill()}ctx.globalAlpha=1;
// paths
ctx.fillStyle='#9ba36a';ctx.beginPath();ctx.moveTo(900-camera.x,0-camera.y);ctx.bezierCurveTo(760-camera.x,300-camera.y,1050-camera.x,430-camera.y,870-camera.x,world.h-camera.y);ctx.lineTo(990-camera.x,world.h-camera.y);ctx.bezierCurveTo(1110-camera.x,430-camera.y,890-camera.x,300-camera.y,1020-camera.x,0-camera.y);ctx.fill();
}
