function drawSlime(s){if(s.dead)return;let q=toScreen(s.x,s.y);ctx.save();ctx.translate(q.x,q.y);ctx.fillStyle='#0004';ctx.beginPath();ctx.ellipse(0,7,20,7,0,0,7);ctx.fill();ctx.fillStyle=s.hit>0?'#f7f0d1':'#78bd76';ctx.beginPath();ctx.moveTo(-18,5);ctx.quadraticCurveTo(-20,-18,0,-21+s.phase%1);ctx.quadraticCurveTo(20,-18,18,5);ctx.quadraticCurveTo(0,13,-18,5);ctx.fill();ctx.fillStyle='#1c422b';ctx.fillRect(-7,-10,3,3);ctx.fillRect(5,-10,3,3);ctx.fillStyle='#d3eea1';ctx.beginPath();ctx.ellipse(-7,-15,4,2,-.5,0,7);ctx.fill();ctx.strokeStyle='#301';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-4,-2);ctx.lineTo(4,-2);ctx.stroke();ctx.restore();if(s.hp<s.maxhp){ctx.fillStyle='#241';ctx.fillRect(q.x-18,q.y-29,36,4);ctx.fillStyle='#cc5e67';ctx.fillRect(q.x-18,q.y-29,36*s.hp/s.maxhp,4)}}
function update(){if(!document.querySelector('.panel.open')){let sp=2.5*(keys.shift?1.7:1);let dx=(keys.d?1:0)-(keys.a?1:0),dy=(keys.s?1:0)-(keys.w?1:0);if(joyv.x||joyv.y){dx=joyv.x;dy=joyv.y}if(dx||dy){let len=Math.hypot(dx,dy)||1;let nx=player.x+dx/len*sp,ny=player.y+dy/len*sp;if(!isBlocked(nx,ny)){player.x=nx;player.y=ny}if(dx)player.dir=dx>0?1:-1;player.anim+=.2}}
 camera.x+=((player.x-W/2)-camera.x)*.08;camera.y+=((player.y-H/2)-camera.y)*.08;camera.x=Math.max(0,Math.min(world.w-W,camera.x));camera.y=Math.max(0,Math.min(world.h-H,camera.y));
 slimes.forEach(s=>{if(s.dead){s.respawn--;if(s.respawn<=0){s.dead=false;s.hp=s.maxhp;s.x=300+Math.random()*1200;s.y=220+Math.random()*800}}else{s.phase+=.05;let d=Math.hypot(player.x-s.x,player.y-s.y);if(d<260){let dx=(player.x-s.x)/Math.max(d,1),dy=(player.y-s.y)/Math.max(d,1);if(d>45){s.x+=dx*.55;s.y+=dy*.55}}if(d<38&&s.hit<=0){player.hp-=.35;s.hit=20}}if(s.hit>0)s.hit--});particles.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.t--});particles=particles.filter(p=>p.t>0);floaters.forEach(f=>{f.y-=.5;f.t--});floaters=floaters.filter(f=>f.t>0);
 player.hp=Math.min(player.maxhp,player.hp+(keys.h?.2:0));player.mp=Math.min(player.maxmp,player.mp+.03);if(player.hp<=0){player.hp=player.maxhp;player.x=900;player.y=600;addChat('[System]','Kau bangkit di Hutan Fae.')} 
}
